import express, { NextFunction, Request, Response } from "express";
import { ProjectService } from "../application/project-service";
import { TaskService } from "../application/task-service";
import { UserService } from "../application/user-service";
import { ConflictError, NotFoundError, ValidationError } from "../domain/errors";
import { isTaskStatus, Task, TaskFilter, TaskStatus, TASK_STATUSES } from "../domain/task";

export interface AppServices {
  users: UserService;
  projects: ProjectService;
  tasks: TaskService;
}

type Body = Record<string, unknown>;

function bodyOf(req: Request): Body {
  const body: unknown = req.body;
  if (body === undefined) {
    return {};
  }
  if (typeof body !== "object" || body === null || Array.isArray(body)) {
    throw new ValidationError("Request body must be a JSON object");
  }
  return body as Body;
}

function requiredString(body: Body, field: string): string {
  const value = body[field];
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new ValidationError(`'${field}' is required and must be a non-empty string`);
  }
  return value;
}

function optionalString(body: Body, field: string): string | undefined {
  const value = body[field];
  if (value === undefined || value === null) {
    return undefined;
  }
  if (typeof value !== "string") {
    throw new ValidationError(`'${field}' must be a string`);
  }
  return value;
}

function optionalDate(body: Body, field: string): Date | undefined {
  const raw = optionalString(body, field);
  if (raw === undefined) {
    return undefined;
  }
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) {
    throw new ValidationError(`'${field}' must be a valid ISO 8601 date`);
  }
  return date;
}

function parseStatus(value: unknown, field: string): TaskStatus | undefined {
  if (value === undefined) {
    return undefined;
  }
  if (!isTaskStatus(value)) {
    throw new ValidationError(`'${field}' must be one of: ${TASK_STATUSES.join(", ")}`);
  }
  return value;
}

function singleQueryValue(req: Request, name: string): string | undefined {
  const value: unknown = req.query[name];
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== "string") {
    throw new ValidationError(`Query parameter '${name}' must be a single value`);
  }
  return value;
}

function taskToJson(task: Task) {
  return {
    id: task.id,
    projectId: task.projectId,
    title: task.title,
    description: task.description,
    dueDate: task.dueDate?.toISOString() ?? null,
    status: task.status,
    assigneeId: task.assigneeId ?? null,
    createdAt: task.createdAt.toISOString(),
    completedAt: task.completedAt?.toISOString() ?? null,
  };
}

export function createApp(services: AppServices): express.Express {
  const app = express();
  app.use(express.json());

  app.get("/health", (_req, res) => {
    res.json({ status: "ok" });
  });

  // Users
  app.post("/users", (req, res) => {
    const body = bodyOf(req);
    const user = services.users.register(requiredString(body, "name"));
    res.status(201).json(user);
  });

  app.get("/users", (_req, res) => {
    res.json(services.users.list());
  });

  app.get("/users/:userId", (req, res) => {
    res.json(services.users.get(req.params.userId));
  });

  // Projects
  app.post("/projects", (req, res) => {
    const body = bodyOf(req);
    const project = services.projects.create(requiredString(body, "name"));
    res.status(201).json(project);
  });

  app.get("/projects", (_req, res) => {
    res.json(services.projects.list());
  });

  app.get("/projects/:projectId", (req, res) => {
    res.json(services.projects.get(req.params.projectId));
  });

  // Tasks
  app.post("/projects/:projectId/tasks", (req, res) => {
    const body = bodyOf(req);
    const task = services.tasks.add({
      projectId: req.params.projectId,
      title: requiredString(body, "title"),
      description: optionalString(body, "description") ?? "",
      dueDate: optionalDate(body, "dueDate"),
      status: parseStatus(body["status"], "status"),
      assigneeId: optionalString(body, "assigneeId"),
    });
    res.status(201).json(taskToJson(task));
  });

  app.get("/projects/:projectId/tasks", (req, res) => {
    const filter: TaskFilter = {};
    const status = parseStatus(singleQueryValue(req, "status"), "status");
    if (status !== undefined) {
      filter.status = status;
    }
    const assigneeId = singleQueryValue(req, "assigneeId");
    if (assigneeId !== undefined) {
      filter.assigneeId = assigneeId;
    }
    const tasks = services.tasks.list(req.params.projectId, filter);
    res.json(tasks.map(taskToJson));
  });

  app.get("/projects/:projectId/tasks/:taskId", (req, res) => {
    const task = services.tasks.get(req.params.projectId, req.params.taskId);
    res.json(taskToJson(task));
  });

  app.put("/projects/:projectId/tasks/:taskId/assignee", (req, res) => {
    const body = bodyOf(req);
    const task = services.tasks.assign(
      req.params.projectId,
      req.params.taskId,
      requiredString(body, "userId"),
    );
    res.json(taskToJson(task));
  });

  app.post("/projects/:projectId/tasks/:taskId/done", (req, res) => {
    const task = services.tasks.markDone(req.params.projectId, req.params.taskId);
    res.json(taskToJson(task));
  });

  app.use((req, res) => {
    res.status(404).json({ error: "NotFound", message: `Route ${req.method} ${req.path} not found` });
  });

  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    if (err instanceof ValidationError) {
      res.status(422).json({ error: err.name, message: err.message });
    } else if (err instanceof NotFoundError) {
      res.status(404).json({ error: err.name, message: err.message });
    } else if (err instanceof ConflictError) {
      res.status(409).json({ error: err.name, message: err.message });
    } else if (err instanceof SyntaxError) {
      res.status(400).json({ error: "BadRequest", message: "Malformed JSON body" });
    } else {
      console.error(err);
      res.status(500).json({ error: "InternalServerError", message: "Unexpected error" });
    }
  });

  return app;
}

