import { ProjectService } from "../application/project-service";
import { TaskService } from "../application/task-service";
import { UserService } from "../application/user-service";
import { createApp } from "./http-app";
import {
  InMemoryProjectRepository,
  InMemoryTaskRepository,
  InMemoryUserRepository,
} from "./in-memory-repositories";
import { SystemClock, UuidGenerator } from "./system-adapters";

const users = new InMemoryUserRepository();
const projects = new InMemoryProjectRepository();
const tasks = new InMemoryTaskRepository();
const ids = new UuidGenerator();
const clock = new SystemClock();

const app = createApp({
  users: new UserService(users, ids),
  projects: new ProjectService(projects, ids, clock),
  tasks: new TaskService(tasks, projects, users, ids, clock),
});

const port = Number(process.env["PORT"] ?? 3000);

app.listen(port, () => {
  console.log(`Task management API listening on http://localhost:${port}`);
});

